// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    bytes32 constant IMPLEMENTATION_SLOT = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
    bytes32 constant ADMIN_SLOT = 0xb53127684a568b3173ae13b9f8a6016e243e63b6e8ee1178d6a717850b5d6103;

    function setUp() public {
        c = new VaultAdapter();
    }

    function testFuzz_property(uint256 seed, address actor) public {
        vm.assume(actor != address(0));
        // drive c through its public proxiableUUID() entry with fuzzed context
        vm.prank(actor);
        bytes32 returned = c.proxiableUUID();
        // general rule: proxiableUUID always reports the ERC-1967 implementation slot,
        // never the admin slot, for any caller/seed
        assertTrue(returned == IMPLEMENTATION_SLOT && returned != ADMIN_SLOT && uint256(seed) >= 0);
    }
}
